(async function(){const status=document.getElementById('stem-public-status');try{const base=window.CAGE_CONFIG?.supabaseUrl;if(!base)throw new Error('Registration is not yet connected. Please contact CAGE.');const response=await fetch(base+'/functions/v1/stem-intake');const data=await response.json();if(!response.ok)throw new Error(data.error||'Registration is temporarily unavailable.');const url=new URL(data.public_url);if(url.protocol!=='https:'||url.hostname!=='docs.google.com'||!url.pathname.startsWith('/forms/')||!url.pathname.endsWith('/viewform'))throw new Error('Registration link unavailable.');const link=document.getElementById('stem-public-link');link.href=url.href;link.hidden=false;if(!data.accepting_responses){status.textContent='Applications are currently closed. Please check back later.';return;}url.searchParams.set('embedded','true');const frame=document.getElementById('stem-public-frame');frame.src=url.href;frame.hidden=false;status.textContent='If the embedded form does not load or asks you to sign in, use the link below.';}catch(e){status.textContent=e.message;}})();
